let arr_vec: ArrayVec<[i32; 10]> = (1..=3).cycle().take(10).collect();
let inner = arr_vec.into_inner();
assert_eq!(inner, [1, 2, 3, 1, 2, 3, 1, 2, 3, 1]);
```

